// The SSH node does NOT fail on a non-zero exit code.
//
// Read in the n8n and node-ssh sources on 2026-09-13: the node returns the
// result of ssh.execCommand() as-is, and that resolves to
// { stdout, stderr, code, signal } -- it never throws on a non-zero exit.
// So without this node, a pipeline that failed every step would still leave a
// green execution in the history. On a weekly schedule nobody watches, that is
// the worst available outcome: silence that looks like success.
//
// Throwing here fails the execution, which shows red in the history AND fires
// the workflow's Error Workflow -- where the notification lives, so this
// workflow never has to know which channel is in use.

const r = $input.first().json;
const exitCode = r.code;
const log = (r.stdout || '').trim();
const err = (r.stderr || '').trim();

// Exit codes are defined in scripts/vps-pipeline.sh:
//   0 everything succeeded | 64 task not on the whitelist
//  69 another run holds the lock | 70 an ingestion or dbt step failed
const meaning = {
  64: 'the task name was refused by the whitelist',
  69: 'another pipeline run was already in progress',
  70: 'an ingestion step or the dbt build failed',
};

if (exitCode !== 0) {
  const why = meaning[exitCode] || 'unexpected exit code';
  throw new Error(
    'MHI pipeline failed -- exit ' + exitCode + ' (' + why + ')\n\n' +
    '--- output ---\n' + log + '\n\n--- errors ---\n' + err
  );
}

// Succeeded: hand the log on so a green execution still shows what was done.
return [{ json: { ok: true, exitCode, log } }];
